module spi_mock_peripheral(
input logic [1:0] EVENT,
input logic SCK,
input logic RST_N,
input logic MOSI,
input logic NORM_CS_N,
input logic START,
input logic ENC_DEC,
input logic [31:0] RESPONSE_WORD,
input logic [106:0] STATE_Q,
output logic [106:0] STATE_D,
output logic [3:0] ERROR,
output logic MISO,
output logic BUSY,
output logic ICE_LED,
output logic [31:0] RECEIVED_WORD,
output logic [31:0] FRAME_COUNT,
output logic [31:0] FRAME_BITS
);
logic q_ready, q_open, q_miso;
logic [1:0] q_rem;
logic [31:0] q_tx, q_rx, q_frames;
logic [5:0] q_bits;
assign q_ready = STATE_Q[106];
assign q_open = STATE_Q[105];
assign q_miso = STATE_Q[104];
assign q_rem = STATE_Q[103:102];
assign q_tx = STATE_Q[101:70];
assign q_rx = STATE_Q[69:38];
assign q_frames = STATE_Q[37:6];
assign q_bits = STATE_Q[5:0];
assign MISO = q_miso;
assign BUSY = (q_rem != 2'd0);
assign ICE_LED = (q_rem != 2'd0);
assign RECEIVED_WORD = q_rx;
assign FRAME_COUNT = q_frames;
assign FRAME_BITS = {26'd0, q_bits};
always_comb begin
STATE_D = STATE_Q;
ERROR = 4'd0;
if (EVENT == 2'd2 && RST_N == 1'b0) begin
STATE_D = 107'd0;
STATE_D[106] = 1'b1;
end else if (q_ready == 1'b1) begin
case (EVENT)
2'd1: begin
if (!(SCK == 1'b0 && NORM_CS_N == 1'b0 && RST_N == 1'b1)) ERROR = 4'd1;
else if (q_open != 1'b0) ERROR = 4'd2;
else if (START != 1'b0) ERROR = 4'd4;
else if (q_rem != 2'd0) ERROR = 4'd5;
else begin
STATE_D[105] = 1'b1;
STATE_D[5:0] = 6'd0;
STATE_D[69:38] = 32'd0;
STATE_D[101:70] = RESPONSE_WORD;
end
end
2'd2: begin
if (SCK != 1'b1) ERROR = 4'd1;
else if (NORM_CS_N == 1'b0) begin
if (q_open != 1'b1) ERROR = 4'd2;
else if (!(q_bits < 6'd32)) ERROR = 4'd3;
else if (START != 1'b0) ERROR = 4'd4;
else if (q_rem != 2'd0) ERROR = 4'd5;
else begin
STATE_D[104] = q_tx[31];
STATE_D[101:70] = {q_tx[30:0], 1'b0};
STATE_D[69:38] = {q_rx[30:0], MOSI};
STATE_D[5:0] = q_bits + 6'd1;
end
end else begin
if (q_open != 1'b0) ERROR = 4'd2;
else if (START == 1'b1) begin
if (q_rem != 2'd0) ERROR = 4'd4;
else STATE_D[103:102] = 2'd3;
end else if (q_rem != 2'd0) begin
STATE_D[103:102] = q_rem - 2'd1;
end
end
end
2'd3: begin
if (!(SCK == 1'b0 && NORM_CS_N == 1'b1)) ERROR = 4'd1;
else if (q_open != 1'b1) ERROR = 4'd2;
else if (q_bits != 6'd32) ERROR = 4'd3;
else begin
STATE_D[105] = 1'b0;
STATE_D[37:6] = q_frames + 32'd1;
end
end
default: begin
STATE_D = STATE_Q;
end
endcase
end
end
endmodule

